import { forwardRef } from "react";
import {
  Pressable,
  type PressableProps,
  StyleSheet,
  type View,
} from "react-native";

type Props = PressableProps & {
  response?: "opacity" | "scale" | "none";
};

export const Wrapper = forwardRef<View, Props>(
  ({ style, children, hitSlop, response = "scale", ...rest }, ref) => {
    return (
      <Pressable
        ref={ref}
        style={
          typeof style === "function"
            ? style
            : ({ pressed }) => [
                style,
                pressed && styles[response],
                rest.disabled && styles.opacity,
              ]
        }
        hitSlop={hitSlop || 12}
        {...rest}
      >
        {children}
      </Pressable>
    );
  },
);

const styles = StyleSheet.create({
  scale: {
    transform: [{ scale: 0.96 }],
  },
  opacity: {
    opacity: 0.66,
  },
  none: {},
});

