              tintColor={Colors.white}
            />

            <Text
              size={TextSize.small}
              font="InstrumentSans-Medium"
              color={Colors.white}
            >
              Invite
            </Text>
          </Block>
        </Button.Wrapper>
      )}
    </Block>
  );
};

